create view public.public_gym_profile with (security_invoker=true) as
 SELECT ( SELECT to_jsonb(p.*) - 'id'::text - 'updated_by'::text - 'active_students_min_display'::text
           FROM public.gym_profile p) AS profile,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(s.*) - 'id'::text ORDER BY s.sort_order), '[]'::jsonb) AS "coalesce"
           FROM public.gym_schedule_slots s) AS schedule,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(k.*) - 'id'::text - 'is_active'::text ORDER BY k.sort_order), '[]'::jsonb) AS "coalesce"
           FROM public.gym_classes k
          WHERE k.is_active) AS classes,
    public.public_active_students_rounded() AS active_students;

